}","newString":"    private static void EnsurePending(Invoice invoice)
    {
        if (invoice.Status != InvoiceStatus.PendingApproval)
        {
            throw new InvalidOperationException(
                $"Invoice {invoice.Id} is {invoice.Status}; only pending invoices can be decided.");
        }
    }

    private static void ValidateFinalApproval(Invoice invoice, string approver)
    {
        if (string.IsNullOrWhiteSpace(approver))
        {
            throw new InvalidOperationException("Approver is required for final approval.");
        }

        var normalizedApprover = approver.Trim();

        if (normalizedApprover.Equals("Manager", StringComparison.OrdinalIgnoreCase))
        {
            if (invoice.Amount > 50000m)
            {
                throw new InvalidOperationException(
                    $"Manager final approval is only allowed for invoices up to 50,000. Invoice {invoice.Id} is {invoice.Amount:C}.");
            }

            return;
        }

        if (normalizedApprover.Equals("Director", StringComparison.OrdinalIgnoreCase))
        {
            if (invoice.Amount <= 50000m || invoice.Amount > 500000m)
            {
                throw new InvalidOperationException(
                    $"Director final approval is only allowed for invoices above 50,000 and up to 500,000. Invoice {invoice.Id} is {invoice.Amount:C}.");
            }

            return;
        }

        throw new InvalidOperationException(
            $"Role '{approver}' is not allowed to provide final approval.");
    }
}"}]}

