rs","location":{"start":{"line":79,"column":5},"end":{"line":93,"column":6}}},{"id":"6fa76c45-cbcf-918b-c61d-d05c24c655c2","name":"InvoiceApp.Tests.AuthAuthorizationTests.AuthController_Login_Returns_Configured_Role_For_Demo_Users","location":{"start":{"line":79,"column":5},"end":{"line":93,"column":6}}}]},"C:\Users\shashwatraghuwanshi\ai-sdlc-demo-app\backend\tests\InvoiceApp.Tests\FakeInvoiceRepository.cs":{"language":"cs","source":"using InvoiceApp.Domain;

